import React from 'react';
import { Link } from 'react-router-dom';
import { postData } from './PostData';
import FeatherIcon from 'feather-icons-react';

const Post = () => {
    return (
        <div className="container-xl px-4 mt-5 mb-5">
            <div className="text-center mb-5">
                <h1 className="display-5 fw-bolder">Posts</h1>
                <p className="lead text-muted">Our latest research stories and insights.</p>
                <hr className="w-25 mx-auto" />
            </div>

            <div className="row gx-5 justify-content-center">
                {postData.map((post) => (
                    <div className="col-lg-6 col-md-6 mb-5" key={post.id}>
                        <Link to={`/post/${post.id}`} className="text-decoration-none">
                            <div className="card h-100 shadow-sm border-0 lift">
                                <div className="card-img-top d-flex align-items-center justify-content-center" style={{ aspectRatio: '16 / 9', backgroundColor: '#f8f9fa', overflow: 'hidden' }}>
                                    <img src={post.image} alt={post.headline} style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain' }} />
                                </div>
                                <div className="card-body p-4">
                                    <div className="d-flex justify-content-between small text-muted mb-2">
                                        <span>{post.date}</span>
                                        <span>{post.category}</span>
                                    </div>
                                    <h5 className="card-title fw-bolder text-dark">{post.headline}</h5>
                                    <p className="card-text text-muted">{post.description}</p>
                                </div>
                                <div className="card-footer bg-transparent border-top-0 p-4 pt-0">
                                    <div className="text-decoration-none d-flex align-items-center" style={{ color: '#8b0029', fontWeight: 'bold' }}>
                                        Read More
                                        <FeatherIcon icon="arrow-right" className="ms-1" style={{ width: 16, height: 16, stroke: '#8b0029' }} />
                                    </div>
                                </div>
                            </div>
                        </Link>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default Post;